// Schema IR: the TypeScript view of the runtime schema document that
// superschematic emits (Go: ir/). Types only; nothing at runtime. The schema
// runtime (@superschematic/schema-runtime) and any scalar package that types
// a schema-document scalar import from here, which keeps the dependency
// graph acyclic: this package imports nothing.

export type DefinitionKind = 'type' | 'input' | 'enum';
export type TypeKind = 'object' | 'input';

export interface Import {
  from: string;
  types: string[];
}

export interface TypeRef {
  name: string;
  isArray: boolean;
  // T[][]: each element of the outer list is a list of `name`. Requires
  // isArray; absent means false.
  isArrayOfArrays?: boolean;
  elemNonNull: boolean;
}

export interface MiddlewareConfig {
  rateLimit: number | null;
  bodyLimit: number | null;
  timeout: number | null;
  encrypted: boolean;
}

export interface RelationDef {
  type: string;
  field: string;
}

export interface IndexDef {
  keys: string[];
  unique: boolean;
}

export interface ArgumentDef {
  name: string;
  description: string;
  typeRef: TypeRef;
  required: boolean;
  defaultValue: string | null;
  isQuery: boolean;
}

export interface FieldDef {
  name: string;
  description: string;
  // Human-facing label (JSON Schema `title` key); absent = derive from name.
  title?: string;
  // Longer-form Markdown explaining what the field is for (`x-purpose`).
  purpose?: string;
  // Name of the glyph a UI shows for the field (`x-icon`).
  icon?: string;
  // Input placeholder hint (`x-placeholder` in the legacy form).
  placeholder?: string;
  jsonKey: string;
  required: boolean;
  autoGenerated: boolean;
  defaultValue: string | null;
  validateMin: number | null;
  validateMax: number | null;
  validateMinLength: number | null;
  validateMaxLength: number | null;
  validateListMin: number | null;
  validateListMax: number | null;
  validatePattern: string;
  arguments: ArgumentDef[];
  key: boolean;
  unique: boolean;
  searchField: boolean;
  relation: RelationDef | null;
  hasMany: boolean;
  manyToMany: boolean;
  jsonField: boolean;
  secret: boolean;
  uiHidden: boolean;
  semanticRole: string;
  // Wire encoding of a Temporal.DateTime field whose source sends a bare
  // epoch count instead of ISO text: unix, unix_millis,
  // unix_micros, or unix_nanos. temporalFormat in the runtime-IR wire form,
  // x-temporal-format in the legacy JSON-Schema form. Empty = ISO text.
  temporalFormat: string;
  // Promote-path transform directives: camelCase transform*
  // flags in the runtime-IR wire form, x-transform* keys in the legacy
  // JSON-Schema form, @transform* directives in GraphQL SDL.
  transformDedupKey: boolean;
  transformOrdering: boolean;
  transformFingerprintInput: boolean;
  transformPartitionDate: boolean;
  transformStructural: boolean;
  transformPersonEmail: boolean;
  transformPersonName: boolean;
  transformAccountId: boolean;
  transformExternalUserId: boolean;
  exclude: boolean;
  internalMetadata: boolean;
  auth: boolean;
  encrypted: boolean;
  requireOwnership: boolean;
  permissions: string[];
  restMethod: string;
  paramType: string;
  middleware: MiddlewareConfig | null;
  typeRef: TypeRef;
}

export interface TypeDef {
  name: string;
  description: string;
  kind: TypeKind;
  fields: FieldDef[];
  indexes: IndexDef[];
  envVars: boolean;
}

export interface EnumValueDef {
  name: string;
  description: string;
  serializedAs: string;
}

export interface EnumDef {
  name: string;
  owner: string;
  description: string;
  values: EnumValueDef[];
}

export interface FileUploadConfig {
  maxSize: number;
  allowedTypes: string[];
  category: string;
}

export interface ImageConstraints {
  maxWidth: number;
  maxHeight: number;
  minAspectRatio: number | null;
  maxAspectRatio: number | null;
  requireTransparency: boolean;
}

export interface ScalarDef {
  name: string;
  description: string;
  primitive: string;
  minLength: number;
  maxLength: number;
  pattern: string;
  format: string;
  reservedWords: string[];
  caseInsensitive: boolean;
  reservedWordsCaseInsensitive: boolean;
  reservedWordsMatchPartial: boolean;
  minimum: number | null;
  maximum: number | null;
  example: string;
  fileUpload: FileUploadConfig | null;
  imageConstraints: ImageConstraints | null;
  hasCustomNormalize: boolean;
  hasCustomValidate: boolean;
  hasCustomParse: boolean;
  typeMappings: Record<string, string>;
}

export interface UnionDef {
  name: string;
  description: string;
  types: string[];
}

export interface OperationSet {
  operations: FieldDef[];
  middleware: MiddlewareConfig | null;
  encrypted: boolean;
}

export interface Schema {
  name?: string;
  kind?: string;
  description?: string;
  rootType?: string;
  imports: Import[];
  scalars?: Record<string, ScalarDef>;
  enums?: Record<string, EnumDef>;
  types?: Record<string, TypeDef>;
  inputs?: Record<string, TypeDef>;
  unions?: Record<string, UnionDef>;
  queries?: OperationSet;
  mutations?: OperationSet;
}

export type SchemaInput = Schema | string | Record<string, unknown>;
